    h,w=len(grid),len(grid[0])
    # Identify separate 4-connected 5 frames and transform each consistently.
    seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=5 or (r,c) in seen: continue
        stack=[(r,c)];seen.add((r,c));comp=[]
        while stack:
          y,x=stack.pop();comp.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<h and 0<=nx<w and grid[ny][nx]==5 and (ny,nx) not in seen:
              seen.add((ny,nx));stack.append((ny,nx))
        top=min(y for y,x in comp);bottom=max(y for y,x in comp)
        left=min(x for y,x in comp);right=max(x for y,x in comp)
        # Hollow area bounded by the frame walls.
        for y in range(top+1,bottom):
          for x in range(left+1,right):
            if grid[y][x]==0:out[y][x]=2
        # Ray begins at upper opening and points opposite the top-edge solid cap.
        top_cols={x for y,x in comp if y==top}
        gaps=[x for x in range(left+1,right) if grid[top][x]==0]
        if gaps and top>0:
          left_cap=sum(x<gaps[0] for x in top_cols)
          right_cap=sum(x>gaps[-1] for x in top_cols)
          if left_cap>right_cap:
            for x in range(right+1,w):out[top-1][x]=2
          else:
            for x in range(0,left):out[top-1][x]=2
    return out
